from pathlib import Path
from html import escape
from PIL import Image
import json, shutil, subprocess, tempfile
from data import products, flange_rows
root=Path(__file__).resolve().parent.parent; site=root/'site'; imgs=site/'assets/img'; imgs.mkdir(parents=True,exist_ok=True)
files={p[2] for p in products}|{'custom_machining_2.jpg','custom_machining_3.jpg','vp_pic02.gif','flangedraw.gif'}|{f'Mv_00{i}.gif' for i in range(1,6)}
files.remove('control-valve.jpg')
with tempfile.TemporaryDirectory() as tmp:
 subprocess.run(['pdfimages', '-f', '8', '-l', '8', '-png', str(site/'assets/docs/pcv.pdf'), str(Path(tmp)/'valve')], check=True)
 Image.open(Path(tmp)/'valve-000.png').convert('RGB').save(imgs/'control-valve.jpg', quality=82, optimize=True)
for f in files:
 im=Image.open(root/'reference/img/images'/f).convert('RGB'); im.save(imgs/(Path(f).stem.lower()+('.jpg' if f.endswith('.jpg') else '.png')),quality=82,optimize=True)
def img(f,alt):
 path=imgs/(Path(f).stem.lower()+('.jpg' if f.endswith('.jpg') else '.png')); im=Image.open(path)
 return f'<img src="/assets/img/{path.name}" alt="{escape(alt)}" width="{im.width}" height="{im.height}" loading="lazy" style="max-width:min(100%, {im.width * 1.25:g}px)">'
def table(headers, rows, label="Specifications"):
 return f'<div class="table-wrap" tabindex="0" role="region" aria-label="{escape(label)}"><table><thead><tr>'+''.join('<th scope="col">'+escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+escape(x)+('</th>' if i==0 else '</td>') for i,x in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def form():
 fields=['Name','Company','Email','Phone','Message']; return '<form class="form" data-subject="Website inquiry"><!-- Replace mailto handler with a production endpoint here. -->'+''.join(f'<label>{x}<'+('textarea' if x=='Message' else 'input')+f' name="{x}"'+(' type="email" autocomplete="email"' if x=='Email' else ' autocomplete="name"' if x=='Name' else ' autocomplete="organization"' if x=='Company' else ' type="tel" autocomplete="tel"' if x=='Phone' else '')+(' required' if x in ['Name','Email','Message'] else '')+('></textarea>' if x=='Message' else '>')+'</label>' for x in fields)+'<button class="button" type="submit">Send inquiry</button><p class="status" role="status"></p></form>'
def quote():
 fields=['Fluid','Gas or liquid','Specific gravity','Temperature range','Delta P','Inlet pressure','Outlet pressure','Normal flow (GPM, SCFM, etc.)','Maximum flow','Calculated Cv','Valve Cv','Quantity','Line size','Type (globe, angle, other)','Body material','Plug material','Stem material','Seat material','Characteristic (linear, percentage, E.D. trim)','Body connection (flanged, screw-end, other)','Fail (open or close)','Air-to (open or close)','Pneumatic range (3-15, 3-9, or 9-15 psi)','Electric range (4-20, 4-12, or 12-20 madc)','Operation (pneumatic, electric, electro-pneumatic)','Completed by','Date','Name','Company','Phone','Fax','Email']; return '<form class="form quote" data-subject="Plastic control valve inquiry"><!-- Replace mailto handler with a production endpoint here. -->'+''.join(f'<label>{escape(x)}<input name="{escape(x)}"'+(' type="email" autocomplete="email" required' if x=='Email' else ' required autocomplete="name"' if x=='Name' else ' type="date"' if x=='Date' else '')+'></label>' for x in fields)+'<button class="button" type="submit">Request a quote</button><p class="status" role="status"></p></form>'
def page(slug,title,body,desc):
 nav=''.join(f'<a href="/{s}/"'+(' aria-current="page"' if slug==s else '')+f'>{t}</a>' for s,t,_,_ in products)
 org={'@context':'https://schema.org','@type':'Organization','name':'Collins Instrument Company, Inc.','url':'https://collinsinst.com/','telephone':'(979) 849-8266','faxNumber':'(979) 848-0783','email':'cic@collinsinst.com','address':{'@type':'PostalAddress','postOfficeBoxNumber':'938','addressLocality':'Angleton','addressRegion':'TX','postalCode':'77516'}}
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>{escape(title)} | Collins Instrument Company</title><meta name="description" content="{escape(desc)}"><meta property="og:title" content="{escape(title)} | Collins Instrument Company"><meta property="og:description" content="{escape(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="https://collinsinst.com/{slug + '/' if slug else ''}"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/css/site.css"><script type="application/ld+json">{json.dumps(org)}</script><script src="/assets/js/site.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><div class="header-inner"><a class="brand" href="/" aria-label="Collins Instrument Company home"><span class="brand-mark">CI</span><span>COLLINS <small>INSTRUMENT COMPANY, INC.</small></span></a><button class="menu" aria-expanded="false" aria-controls="nav">Menu <span>☰</span></button><nav id="nav" aria-label="Main navigation">{nav}<a href="/contact/" {'aria-current="page"' if slug=='contact' else ''}>Contact</a></nav><a class="header-phone" href="tel:+19798498266">(979) 849-8266</a></div></header><main id="main">{body}</main><footer><div class="wrap footer-grid"><div><strong>Collins Instrument Company, Inc.</strong><p>P.O. Box 938<br>Angleton, TX 77516</p></div><div><a href="tel:+19798498266">(979) 849-8266</a><br>Fax: (979) 848-0783<br><a href="mailto:cic@collinsinst.com">cic@collinsinst.com</a></div><a href="/contact/">Contact us →</a></div></footer></body></html>'''
 out=site/slug/'index.html' if slug else site/'index.html'; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(html)
def hero(title,text=''):
 return f'<section class="page-hero"><div class="wrap"><h1>{title}</h1></div></section>'
def cta(): return '<section class="contact-band"><div class="wrap band-inner"><h2>Contact</h2><a href="tel:+19798498266">(979) 849-8266</a><a class="button light" href="/contact/">Contact us <span>↗</span></a></div></section>'
cards=''.join(f'<a class="card" href="/{s}/"><div class="card-image">{img(im,t)}</div><div class="card-copy"><h3>{t} <span>↗</span></h3></div></a>' for s,t,im,d in products)
home='''<section class="hero"><div class="wrap hero-grid"><div><h1>Plastic control valves and precision machining</h1><p>Collins Instrument Company provides close tolerance, precision machined parts and products to the industrial marketplace.</p><div class="actions"><a class="button" href="#products">Explore products <span>↓</span></a><a class="text-link" href="/contact/">Contact us ↗</a></div></div></div></section><section class="section" id="products"><div class="wrap"><div class="section-heading"><h2>Products &amp; services</h2></div><div class="cards">'''+cards+'''</div></div></section><section class="section pale"><div class="wrap split"><div><h2>Capabilities</h2></div><div><p>We stock our own line of specialized control valves, flareless tube fittings, grounding rings, and precision-machined control valve trim parts. We also welcome the opportunity to tailor products to your specifications.</p><ul class="capabilities"><li>High precision machining</li><li>Custom design</li><li>Plastics and exotic alloys</li><li>Certified TIG and MIG welding</li></ul></div></div></section>'''+cta()
page('','Plastic control valves and precision machining',home,'Precision machined parts, control valves, fittings, grounding rings and valve trim from Collins Instrument Company.')
from valve_tables import valve_tables
body=hero('Plastic control valves','For corrosive media and corrosive atmospheres.')+'''<section class="section"><div class="wrap split"><div><h2>Overview</h2>'+img('control-valve.jpg','Plastic control valve')+'</div><div><p>Collins plastic control valves are designed for use with corrosive media and/or corrosive atmospheres. They are suitable for chemical, petrochemical, pulp and paper, and municipal applications.</p><p>Valves are available in globe, angle, or corner configurations, with a positioner for throttling control or without a positioner for ON-OFF applications. A wide selection of trim sizes is available.</p><p>Applications include acids, bleaches, alkalis, pH control, wastewater, chlorine, chemicals and other corrosive liquids.</p><a class="button" href="/assets/docs/pcv.pdf">Download control valve brochure (PDF) ↗</a></div></div></section><section class="section pale"><div class="wrap split"><h2>Valve options</h2><div><p>The Model 1060B is furnished with a 1” 150# flanged body, PTFE bellows seal, PVDF trim and pneumatic or electric actuator. Optional features include energy dissipating trim, current-to-pneumatic transducers and limit switches.</p><p>Electric actuators and electropneumatic positioners are available for 1/2”, 3/4”, 1” or 2” split-body, globe-style plastic control valves. Collins also offers repair and calibration service for its plastic control valves.</p></div></div></section><section class="section"><div class="wrap"><h2>Specifications and selection</h2>'''+''.join('<h3>'+escape(title)+'</h3>'+table(headers, rows, title) for title, headers, rows in valve_tables)+'''</div></section><section class="section"><div class="wrap"><h2>Valve specification inquiry</h2>'''+quote()+'</div></section>'+cta()
page('control-valves','Plastic Control Valves',body,'Plastic control valves for corrosive applications, including bellows seal valves and actuator options.')
models=['Needle Valve','2-Way Ball Valve','3-Way Ball Valve','Gravity Lift Check Valve','Inline Check Valve']
body=hero('Fittings & valves','Custom fittings and miniature valves in exotic alloys.')+'<section class="section"><div class="wrap split"><h2>Made to order</h2><div><p>Collins tube fittings and miniature valves are available in Hastelloy B/C, Zirconium, Titanium, Nickel 200, Inconel 600 and Alloy 20. Other materials may be available on request.</p></div></div></section><section class="section pale"><div class="wrap"><h2>Miniature valves</h2><div class="model-grid">'+''.join(f'<article><div class="model-img">{img(f"Mv_00{i}.gif",f"Model {i}000 {name}")}</div><h3>Model {i}000</h3><p>{name}</p></article>' for i,name in enumerate(models,1))+'</div></div></section>'+cta()
page('fittings-valves','Fittings & Valves',body,'Custom tube fittings and miniature valves in exotic alloys.')
body=hero('Isolating flanges','Ground out unwanted signals in lined pipe.')+'<section class="section"><div class="wrap split"><div>'+img('flanges_1.jpg','Isolating flanges')+'</div><div><p>Collins manufactures isolating grounding flanges equipped with a metal insert whose tip contacts the flowing medium and allows the user to ground out unwanted signals. They are usually used with lined pipe where a grounding device is required, for instance with magnetic flow meters.</p><p>Flanges are available in polypropylene or PVDF (Kynar*), in sizes from 1/4” to 36”, and in both 150# and 300# ANSI ratings. Our 1” thick flanges have a Monel insert tipped in Tantalum. Other inserts can be custom-tipped with Hastelloy B &amp; C, Titanium, Zirconium, Monel and Platinum.</p><p>Kynar 150# ANSI flanges with Tantalum inserts are stocked up to 6”. Other sizes are available up to 36” in 2–3 weeks after receipt of order.</p></div></div></section><section class="section pale"><div class="wrap"><h2>Specifications</h2>'+img('flangedraw.gif','Isolating flange dimensional drawing')+table(['Size','Part #','O.D.','I.D.','Bolting','Dimensions'],flange_rows)+'<p class="fine">*Kynar is a registered trademark of Elf Atochem North America, Inc. Monel is a registered trademark of Special Metals Corporation. Hastelloy is a registered trademark of Haynes International, Inc.</p></div></section>'+cta()
page('isolating-flanges','Isolating Flanges',body,'Isolating grounding flanges with metal inserts for lined pipe and magnetic flow meters.')
body=hero('Grounding rings','All-metal grounding rings for magnetic flow meters.')+'<section class="section"><div class="wrap split"><div>'+img('grounding_rings.jpg','Grounding rings')+'</div><div><p>Collins all-metal grounding rings fit between flanges, helping to eliminate unwanted noise and extraneous signals carried in fluids through lined pipes. They are available in 316 SS, Hastelloy B &amp; C, Monel, Alloy 20, Titanium, Zirconium and Tantalum, in both 150# and 300# ANSI ratings.</p><p>Paddle-type rings are available in a standard thickness of 1/8”. Tantalum rings are also available in 1/16” thickness. Other styles can be specially fabricated to customer specifications.</p><p>Many exotic alloy rings are stocked in a variety of materials up to 6”. Other sizes are available up to 36” in 2–3 weeks after receipt of order.</p><p class="fine">Monel is a registered trademark of Special Metals Corporation. Hastelloy is a registered trademark of Haynes International, Inc.</p></div></div></section>'+cta()
page('grounding-rings','Grounding Rings',body,'All-metal grounding rings in exotic alloys for lined pipe and magnetic flow meters.')
body=hero('Valve parts & trim','Replacement control valve trim and accessories.')+'<section class="section"><div class="wrap split"><div class="image-stack">'+img('vp_pic01.gif','Control valve parts')+img('vp_pic02.gif','Control valve trim')+'</div><div><p>Collins specializes in the manufacture, inventory and delivery of standard replacement control valve trim and accessories. Parts include stem finishes of 3–4 microinch, roller burnished. Trim and accessories are available in exotic materials as well as stainless steel for corrosive applications.</p><p>Collins can maintain a specialized inventory of custom replacement parts and offer parts with custom modifications for individual processing requirements.</p></div></div></section>'+cta()
page('valve-parts-trim','Valve Parts & Trim',body,'Standard replacement control valve trim and accessories in stainless steel and exotic materials.')
body=hero('Custom machining','Close-tolerance, high-precision products for industrial applications.')+'<section class="section"><div class="wrap split"><h2>Built to your requirements</h2><div><p>Collins produces replacement parts for existing equipment from sample parts or design drawings, and can custom-design and furnish parts to customer specifications.</p><p>Capabilities include high precision machining, custom design, machining of plastics and exotic alloys, and certified TIG and MIG welding. Applications include chemical plants, medical equipment manufacturers, pulp and paper mills, and OEM replacement parts.</p><h3>Materials</h3><p>Hastelloy B and C, Zirconium, Nickel 200, Tantalum, Inconel 600, Titanium and Alloy 20 Cb3.</p><p class="fine">Hastelloy is a registered trademark of Haynos International, Inc. Inconel 600 is a registered trademark of the Inco family of companies. Alloy 20 Cb3 is a registered trademark of Carpenter Technology Corp.</p></div></div><div class="photo-row">'+''.join(f'<a href="/assets/img/custom_machining_{i}.jpg">{img(f"custom_machining_{i}.jpg","Custom machining")}</a>' for i in ['1b','2','3'])+'</div></section>'+cta()
page('custom-machining','Custom Machining',body,'High precision machining, custom design, plastics and exotic alloys, and certified TIG and MIG welding.')
body=hero('Contact','Collins Instrument Company, Inc.')+'<section class="section"><div class="wrap contact-grid"><div><h2>Get in touch</h2><address>P.O. Box 938<br>Angleton, TX 77516</address><p><a href="tel:+19798498266">(979) 849-8266</a><br>Fax: (979) 848-0783<br><a href="mailto:cic@collinsinst.com">cic@collinsinst.com</a></p></div><div><h2>Send an inquiry</h2>'+form()+'</div></div></section>'
page('contact','Contact',body,'Contact Collins Instrument Company in Angleton, Texas.')
(site/'404.html').write_text((site/'contact/index.html').read_text().replace('<h1>Contact</h1>','<h1>Page not found</h1>').replace('<title>Contact |','<title>Page not found |'))
(site/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://collinsinst.com/'+s+'</loc></url>' for s in ['']+[p[0]+'/' for p in products]+['contact/'])+'</urlset>')
(site/'robots.txt').write_text('User-agent: *\nDisallow: /\nSitemap: https://collinsinst.com/sitemap.xml\n')
